PATCH
python3 -m py_compile openai_client.py
python3 - <<'PY'
import io
import json
from unittest.mock import patch

import openai_client


def run(payload=None, headers=None):
    class Response(io.BytesIO):
        def __init__(self):
            super().__init__(b\"\" if payload is None else json.dumps(payload).encode())
            self.headers = headers or {}

        def __enter__(self):
            return self

        def __exit__(self, *args):
            self.close()

    with patch.object(openai_client, \"urlopen\", lambda *args, **kwargs: Response()):
        return openai_client.OpenAIClient(api_key=\"secret\").send_text(
            \"prompt\", model=\"test-model\"
        )


assert run({
    \"output\": [{
        \"type\": \"message\",
        \"content\": [{\"type\": \"output_text\", \"text\": \"answer\"}],
    }],
}, {\"x-request-id\": \"req_123\"}) == \"answer\"

try:
    run({\"error\": {\"type\": \"invalid_request_error\", \"code\": \"bad_model\", \"param\": \"model\"}})
except openai_client.OpenAIHTTPError as exc:
    assert exc.status_code == 200
    assert exc.error_code == \"bad_model\"
    assert exc.error_param == \"model\"
    assert \"secret\" not in str(exc) and \"prompt\" not in str(exc)
else:
    raise AssertionError(\"structured API error was not raised\")

try:
    run(None, {\"x-request-id\": \"req_bad\"})
except openai_client.OpenAIError as exc:
    assert \"invalid JSON\" in str(exc) and \"req_bad\" in str(exc)
else:
    raise AssertionError(\"invalid JSON was not rejected\")

print(\"compile and edge-case checks passed\")
PY"

